// Spawns a particle effect together with its layers (flash, embers, smoke, shockwave … — see particle_layers.js,
// generated by tools/gen_particles.py). Every layer gets the same colour as the base effect.
// A per-tick budget keeps a busy fight from flooding clients: past it, only the base effects are spawned.

import { system, MolangVariableMap } from "@minecraft/server";
import { LAYERS } from "./particle_layers.js";

const BUDGET = 160; // layer spawns per tick, server-wide
let tick = -1;
let used = 0;

export function spawnLayered(dim, id, loc, color) {
  let vars;
  if (color) {
    vars = new MolangVariableMap();
    vars.setColorRGB("variable.color", { red: color[0], green: color[1], blue: color[2] });
  }
  const one = (pid) => {
    try {
      if (vars) dim.spawnParticle(pid, loc, vars);
      else dim.spawnParticle(pid, loc);
    } catch {
      /* unknown particle or unloaded chunk */
    }
  };
  one(id);
  const layers = LAYERS[id];
  if (!layers) return;
  if (system.currentTick !== tick) {
    tick = system.currentTick;
    used = 0;
  }
  for (const pid of layers) {
    if (used >= BUDGET) return;
    used++;
    one(pid);
  }
}
